#include<stdio.h>
#include<string.h>

int main(int argc, char *argv[])
{
    char str[101];
    int i,t,j;

    fgets(str, sizeof(str), stdin);

    for(i=0;i<strlen(str);i=i+2){
        for(j=0;j+2<strlen(str);j=j+2){
            if(str[j+2]<str[j]){
                t=str[j];
                str[j]=str[j+2];
                str[j+2]=t;
            }
        }
    }

    printf("%s", str);
    return 0;
}

